      "보유 보험계약마진이 2025년 말 7조 5,549억 원에서 2026년 9월 말 **8조 423억 원**으로 늘어 역대 최대를 기록했어요. 앞으로 나눠서 이익이 될 몫이 꾸준히 쌓이고 있어요.",
      "천상영 대표는 '신뢰 우선'을 앞세운 **균형 성장**을 경영 방향으로 잡았어요. 외형 경쟁보다 수익성 중심으로 영업의 질을 높이겠다는 뜻이고, 취임 뒤 손해율 전담 조직을 새로 만들었어요.",
      "요양 자회사 신한라이프케어가 2026년 1월 경기 하남 미사에 1인실 요양시설 '쏠라체 홈 미사'를 열었고, 성남 분당 데이케어센터와 부산 해운대 복합시설로 넓혀가고 있어요.",
      "해외에서는 2022년 1월 세운 베트남 법인을 운영해요. 아직 적자라서 흑자 전환이 과제로 꼽혀요."
