          "q": "금리가 오르자 투자손익은 적자가 됐는데 지급여력비율도 내려갔어요. 금리 상승이 자산과 부채에 각각 어떤 영향을 줬을지 생각해볼까요?",
          "hint": "채권 평가이익, 보험금융비용, 보험부채 할인율이 함께 움직인다는 점과 경과조치 전후 비율 차이를 살펴보세요."
