    "summary": "2023년 1월 KB생명과 푸르덴셜생명이 하나로 합쳐 출범한 KB금융그룹의 생명보험사예요. 출범 당시 생명보험업계 8위였고 2030년 업계 3위를 목표로 내걸었으며, 2025년 순이익은 **2,440억 원**이었어요.",
