      "자본이 약한 편이라 그룹 지원과 자본 확충이 이어지고 있어요. 2024년 하나금융지주가 약 2,000억 원을 유상증자로 넣었고, 2026년 3분기에는 1,500억 원 규모 신종자본증권을 발행했어요. 그래도 지급여력비율(킥스, 경과조치 후)은 2025년 9월 말 178.8%에서 2026년 9월 말 134.6%로 내려갔어요.",
