      "보험계약마진이 2026년 1분기 말 2조 530억 원으로 처음 2조 원을 넘었어요. 보험부채 대비 보험계약마진 비중이 22.3%로, 22개 생명보험사 평균 8.3%의 두 배를 훌쩍 넘어요.",
      "2025년 순이익이 1,816억 원으로 24% 늘었고 자기자본이익률은 15.93%였어요. 한국신용평가는 2025년 6월 보험금 지급능력 등급을 더블에이마이너스에서 더블에이로 한 단계 올렸어요.",
