      "소비자보호에 공을 들여요. 불완전판매율이 2020년 0.06%에서 2025년 상반기 0.03%로 낮아져 업계 최상위 수준이고, 2023년 업계 처음으로 법인보험대리점과 내부통제 협약을 맺은 뒤 2025년까지 12곳으로 넓혔어요. 소비자중심경영 인증도 5회 연속 받았어요."
